def _safe_slug(value: str) -> str:
    txt = str(value or "").strip().lower()
    out = []
    for ch in txt:
        if ch.isalnum() or ch in {"-", "_"}:
            out.append(ch)
        elif ch in {" ", ".", "/"}:
            out.append("-")
    slug = "".join(out).strip("-")
    return slug or "run"


